 private static final int NAVY=Color.rgb(16,45,68),TEAL=Color.rgb(23,107,91),MUTED=Color.rgb(89,108,121),BG=Color.rgb(242,246,248);
 private final ExecutorService work=Executors.newSingleThreadExecutor();
