 private CryptoStore store;private BridgeApi api;
 private LinearLayout root,body,header;private ListView list;private TextView titleView,statusView,companyView;private ProgressBar progress;
 private boolean unlocked=false,visible=false,authenticating=false,loginRunning=false,destroyed=false,pollBusy=false;
 private volatile int generation=0;private int loginSerial=0;
 private boolean pdfBusy=false,pairBusy=false;
 private String company="",tab="Home";private JSONObject boot=new JSONObject();
 private final ArrayDeque<Runnable> history=new ArrayDeque<>();private Runnable current;
 private final Map<String,JSONObject> cache=new HashMap<>();private final Map<String,Long> cacheAt=new HashMap<>();
 private boolean forceNext=false;private File savePDF;private CancellationSignal unlockSignal;
 private final NumberFormat currency=NumberFormat.getCurrencyInstance(new Locale("en","IN"));
 private final Runnable poll=new Runnable(){public void run(){if(visible&&unlocked&&!loginRunning&&!pollBusy&&!store.get("device").isEmpty()){pollBusy=true;final int epoch=generation;work.execute(()->{try{JSONObject data=api.get("/api/v1/mobile/status");main.post(()->{if(!destroyed&&unlocked&&epoch==generation){boot=data;updateStatus();if(tab.equals("Home")&&history.isEmpty()&&current!=null)renderHome();}});}catch(Exception e){main.post(()->{if(!destroyed&&unlocked&&epoch==generation){if(e instanceof Http.Failure&&(((Http.Failure)e).status==401||((Http.Failure)e).status==403)){cache.clear();cacheAt.clear();showFailure(e);}else if(statusView!=null)statusView.setText("PC connection unavailable • retrying");}});}finally{main.post(()->pollBusy=false);}});}main.postDelayed(this,15000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);currency.setCurrency(Currency.getInstance("INR"));try{store=new CryptoStore(this);api=new BridgeApi(store);company=store.get("company");cleanPDFs();}catch(Exception e){fatal(e);return;}main.postDelayed(poll,15000);}
 @Override protected void onResume(){super.onResume();visible=true;if(store==null)return;if(loginRunning){simple("Google sign-in","Choose your Google account to continue.","Cancel sign-in",()->{api.login.cancel();loginSerial++;loginRunning=false;showLock();});return;}if(!unlocked&&!authenticating)showLock();}
 @Override protected void onStop(){super.onStop();visible=false;if(!authenticating){unlocked=false;generation++;cache.clear();cacheAt.clear();} }
 @Override protected void onDestroy(){destroyed=true;generation++;main.removeCallbacksAndMessages(null);if(unlockSignal!=null)unlockSignal.cancel();if(api!=null)api.login.cancel();work.shutdownNow();super.onDestroy();}
 private void fatal(Exception e){TextView v=new TextView(this);v.setPadding(30,60,30,30);v.setText("TallyBridge could not start.\n"+e.getMessage());setContentView(v);}
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(dp(4),dp(5),dp(4),dp(5));return v;}
