 private void reports(){List<Row> data=new ArrayList<>();data.add(heading("Daily work","Registers and customer reports"));data.add(row("Today's dispatch","Invoices with dispatch details","",()->open(this::dispatch)));data.add(row("Outstanding ageing","Saved bill coverage shown","",()->open(this::ageing)));data.add(row("Universal search","Find an invoice or customer","",()->open(this::search)));data.add(row("Customer 360","Select a customer from Ledgers","",()->open(()->ledgers(false))));data.add(row("Sales register","Financial year → month → invoice","",()->open(()->register("sales"))));data.add(row("Purchase register","Financial year → month → voucher","",()->open(()->register("purchase"))));for(String name:new String[]{"Day Book","Trial Balance","Profit and Loss","Balance Sheet"})data.add(row(name,"Accounting report","",()->open(()->genericReport(name))));data.add(row("Bills receivable","Customer balances","",()->open(()->outstanding("receivable"))));data.add(row("Bills payable","Supplier balances","",()->open(()->outstanding("payable"))));local("Reports",this::reports,data,false);}
 private void register(String kind){String title=kind.equals("purchase")?"Purchase register":"Sales register";load(title,path("vouchers","type",kind,"period","fy","refresh","1"),()->register(kind),x->{List<Row> data=withSource(x);data.add(row("Financial-year total",x.optInt("count")+" vouchers",money(x.optDouble("total")),null));JSONArray a=array(x,"vouchers");TreeMap<String,JSONArray> months=new TreeMap<>(Collections.reverseOrder());LocalDate now=LocalDate.now();LocalDate fy=LocalDate.of(now.getMonthValue()<4?now.getYear()-1:now.getYear(),4,1);for(int i=0;i<12;i++)months.put(fy.plusMonths(i).toString().substring(0,7),new JSONArray());for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v==null)continue;String date=v.optString("date"),month=date.length()>=7?date.substring(0,7):"Unknown";if(!months.containsKey(month))months.put(month,new JSONArray());months.get(month).put(v);}data.add(row("All vouchers","Search the complete register","",()->open(()->vouchers(title,a,x))));for(Map.Entry<String,JSONArray> entry:months.entrySet()){String month=entry.getKey();JSONArray values=entry.getValue();double total=0;for(int i=0;i<values.length();i++)total+=Math.abs(values.optJSONObject(i).optDouble("amount"));data.add(row(monthLabel(month),values.length()+" vouchers",money(total),()->open(()->vouchers(monthLabel(month),values,x))));}rows(title,data,false);});}
 private void vouchers(String title,JSONArray vouchers,JSONObject source){List<Row> data=withSource(source);addVouchers(data,vouchers);empty(data,vouchers.length(),"No vouchers in this period.");local(title,()->vouchers(title,vouchers,source),data,true);}
 private void addVouchers(List<Row> data,JSONArray a){for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v==null)continue;data.add(row(v.optString("number","Voucher"),v.optString("party")+"\n"+v.optString("date")+" • "+v.optString("voucherType"),money(v.optDouble("amount")),()->open(()->invoice(v))));}}
 private void invoice(JSONObject hint){String id=hint.optString("masterId");if(id.isEmpty()){toast("Refresh this register to obtain the voucher identifier");goBack();return;}load("Invoice "+hint.optString("number"),path("voucher-detail","masterId",id,"number",hint.optString("number"),"date",hint.optString("date"),"party",hint.optString("party"),"amount",hint.optString("amount")),()->invoice(hint),x->{List<Row> data=withSource(x);data.add(heading(x.optString("firmName",company),x.optString("voucherType")));data.add(row(x.optString("customerName"),x.optString("customerCity")+"\n"+join(array(x,"customerAddress"))+"\n"+x.optString("gstin"),"",null));data.add(row("Invoice "+x.optString("invoiceNumber"),x.optString("invoiceDate"),money(x.optDouble("totalAmount")),null));for(String key:new String[]{"dispatchedThrough","lrNumber","lrDate","destination","vehicleNumber","eWayBillNumber"})if(!x.optString(key).isEmpty())data.add(row(label(key),x.optString(key),"",null));JSONArray items=array(x,"items");for(int i=0;i<items.length();i++){JSONObject it=items.optJSONObject(i);if(it==null)continue;data.add(row((i+1)+". "+it.optString("name"),"Quantity "+it.optString("quantity")+" • Rate "+it.optString("rate")+(it.optString("hsn").isEmpty()?"":" • HSN "+it.optString("hsn")),money(it.optDouble("amount")),null));}for(String key:new String[]{"discountAmount","taxableAmount","cgst","sgst","igst","freight","roundOff"})if(x.optDouble(key)!=0)data.add(row(label(key),"",money(x.optDouble(key)),null));data.add(row("Total amount","",money(x.optDouble("totalAmount")),null));if(!x.optString("narration").isEmpty())data.add(row("Narration",x.optString("narration"),"",null));String bank=object(boot,"pdfBanks").optString(company.trim().toLowerCase(Locale.ROOT));data.add(heading("PDF bank",bank.isEmpty()?"No bank details selected. Set the default once on the PC.":bank+" • saved on the PC"));shareRows(data,x.optString("shareText"),path("voucher-pdf","masterId",id),"Invoice-"+x.optString("invoiceNumber"));rows("Invoice "+x.optString("invoiceNumber"),data,false);});}
 private void genericReport(String name){load(name,path("report","name",name),()->genericReport(name),x->{List<Row> data=withSource(x);JSONArray a=array(x,"rows");for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v==null)continue;StringBuilder detail=new StringBuilder();Iterator<String> keys=v.keys();while(keys.hasNext()){String k=keys.next();detail.append(label(k)).append(": ").append(v.optString(k)).append('\n');}data.add(row("Entry "+(i+1),detail.toString().trim(),"",null));}empty(data,a.length(),"Tally returned no normalized rows for this report.");rows(name,data,true);});}
 private void search(){load("Universal search",path("search-index"),this::search,x->{List<Row> data=withSource(x);data.add(heading("Search saved information","Invoice and LR/RR search covers the data already synced or opened."));JSONArray a=array(x,"results");for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v==null)continue;String ledger=v.optString("ledger",v.optString("party",v.optString("title")));data.add(row(v.optString("title"),v.optString("subtitle")+" "+v.optString("number")+" "+v.optString("lrNumber"),v.has("amount")?money(v.optDouble("amount")):"",()->open(v.optString("masterId").isEmpty()?()->ledger(ledger):()->invoice(v))));}empty(data,a.length(),"No saved search results yet.");rows("Universal search",data,true);});}
 private void dispatch(){load("Today's dispatch",path("today-dispatch"),this::dispatch,x->{List<Row> data=withSource(x);data.add(row("Today's total",x.optInt("count")+" vouchers",money(x.optDouble("total")),null));JSONArray a=array(x,"vouchers");addVouchers(data,a);empty(data,a.length(),"No dispatch vouchers returned for today.");rows("Today's dispatch",data,true);});}
 private void ageing(){load("Outstanding ageing",path("ageing"),this::ageing,x->{List<Row> data=withSource(x);data.add(heading("Saved bill coverage",x.optInt("coveredParties")+" of "+x.optInt("totalParties")+" parties • "+x.optInt("coveragePercent")+"%\nOpen a customer's outstanding report to add bill details. Partial coverage is not the complete receivable total."));data.add(row("Covered outstanding",x.optInt("billCount")+" bills",money(x.optDouble("total")),null));JSONArray a=array(x,"buckets");for(int i=0;i<a.length();i++){JSONObject b=a.optJSONObject(i);if(b!=null)data.add(row(b.optString("label"),b.optInt("bills")+" bills",money(b.optDouble("amount")),null));}rows("Outstanding ageing",data,false);});}
